sql_calls.sql:
SELECT sku, name, flow
FROM store.products
WHERE name ILIKE '%curd%' OR name ILIKE '%yogurt%';

SELECT SUM(units) AS total_units_ordered
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT DISTINCT count_date::date
FROM store.stock_counts
ORDER BY count_date;

SELECT DISTINCT count_ts::date
FROM store.stock_counts
ORDER BY count_ts::date;

SELECT sku, name, price_inr
FROM store.products
ORDER BY price_inr;

SELECT *
FROM store.shelf_audits
LIMIT 20;

SELECT COUNT(*) AS products_above_100
FROM store.products
WHERE price_inr > 100;

SELECT SUM(adjustment) AS total_count_adjustments
FROM store.stock_counts
WHERE count_ts >= '2026-06-01' AND count_ts < '2026-07-01';

SELECT SUM(CASE WHEN adjustment < 0 THEN adjustment ELSE 0 END) AS total_negative_adjustments
FROM store.stock_counts
WHERE count_ts >= '2026-06-01' AND count_ts < '2026-07-01';

SELECT COUNT(*) as shelf_audit_rows
FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01';

SELECT *
FROM warehouse.shipments
LIMIT 20;

SELECT *
FROM warehouse.pick_confirmations
LIMIT 20;

SELECT *
FROM store.store_orders
LIMIT 20;

SELECT *
FROM warehouse.stock_adjustments
LIMIT 20;

SELECT *
FROM warehouse.shipments
WHERE dispatched_ts IS NULL;

SELECT *
FROM warehouse.shipping_notice_lines
LIMIT 20;

SELECT *
FROM store.goods_receipts
LIMIT 20;

SELECT *
FROM warehouse.pallets
LIMIT 20;

SELECT *
FROM store.write_offs
LIMIT 20;

SELECT *
FROM store.products
LIMIT 20;

SELECT *
FROM payments.pos_payments
LIMIT 20;

SELECT *
FROM store.goods_receipts
WHERE received_ts::date = '2026-06-12';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'write_offs';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'shelf_audits';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'pos_lines';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'payments' AND table_name = 'customer_complaints';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'payments' AND table_name = 'upi_refunds';

SELECT SUM(units_sold) AS total_units_june_2026
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT sku, name
FROM store.products
WHERE name ILIKE '%bread%';

SELECT COUNT(DISTINCT bill_id) AS bill_count_march_2026
FROM store.pos_lines
WHERE bill_ts >= '2026-03-01' AND bill_ts < '2026-04-01';

SELECT COUNT(*) AS complaints_june_2026
FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';
